Translate the following Java 8 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.util.*;
public class Main {

    static class Metrics {
        boolean inside;
        int maxOutside = -1;
        int currentOutside = 0;
        int currentInside = 0;
        int insideWords = 0;

        void processOutside(char c) {
            if (isAlpha(c)) {
                currentOutside++;
            }
            if (currentOutside > 0 && (c == '_' || c == '(')) {
                maxOutside = Math.max(maxOutside, currentOutside);
                currentOutside = 0;
            }
        }

        void processInside(char c) {
            if (isAlpha(c)) {
                currentInside++;
            }
            if (c == '_' || c == ')') {
                if (currentInside > 0) {
                    insideWords++;
                    currentInside = 0;
                }
                if (c == ')') {
                    inside = false;
                }
            }
        }

        void maybeEnterParenthesis(char c) {
            if (c == '(') {
                inside = true;
            }
        }

        void finish() {
            if (currentOutside > 0) {
                maxOutside = Math.max(maxOutside, currentOutside);
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String s = sc.next();

        Metrics m = new Metrics();

        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (m.inside) {
                m.processInside(c);
            } else {
                m.processOutside(c);
            }
            m.maybeEnterParenthesis(c);
        }

        m.finish();

        System.out.print((m.maxOutside == -1 ? 0 : m.maxOutside) + " ");
        System.out.println(m.insideWords);
    }

    static boolean isAlpha(char a) {
        return (a >= 'A' && a <= 'Z') || (a >= 'a' && a <= 'z');
    }
}
